import subprocess
import json

# Query local server
local_result = subprocess.run(['sonarless-mcp', 'search', '--server', 'local', '--format', 'json'], capture_output=True, text=True)
local_issues = json.loads(local_result.stdout) if local_result.returncode == 0 else {"issues": []}

# Query remote server
remote_result = subprocess.run(['sonarless-mcp', 'search', '--server', 'work', '--format', 'json'], capture_output=True, text=True)
remote_issues = json.loads(remote_result.stdout) if remote_result.returncode == 0 else {"issues": []}

print(f"Local issues: {len(local_issues.get('issues', []))}")
print(f"Remote issues: {len(remote_issues.get('issues', []))}")

# Group by severity
def group_by_severity(issues):
    grouped = {}
    for issue in issues.get('issues', []):
        severity = issue.get('severity', 'UNKNOWN')
        if severity not in grouped:
            grouped[severity] = []
        grouped[severity].append(issue)
    return grouped

local_by_severity = group_by_severity(local_issues)
remote_by_severity = group_by_severity(remote_issues)

print("\n=== LOCAL SERVER ===")
for severity in ['BLOCKER', 'CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO']:
    if severity in local_by_severity:
        print(f"{severity}: {len(local_by_severity[severity])}")

print("\n=== REMOTE SERVER (CI) ===")
for severity in ['BLOCKER', 'CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO']:
    if severity in remote_by_severity:
        print(f"{severity}: {len(remote_by_severity[severity])}")

# Find differences
local_keys = {(i['file'], i['line'], i['message']) for i in local_issues.get('issues', [])}
remote_keys = {(i['file'], i['line'], i['message']) for i in remote_issues.get('issues', [])}

only_in_local = local_keys - remote_keys
only_in_remote = remote_keys - local_keys

print(f"\n=== DIFFERENCES ===")
print(f"Only in local: {len(only_in_local)}")
print(f"Only in remote (CI): {len(only_in_remote)}")

if only_in_local:
    print("\nIssues only in LOCAL:")
    for file, line, msg in sorted(only_in_local)[:5]:
        print(f"  {file}:{line} - {msg[:60]}")
    if len(only_in_local) > 5:
        print(f"  ... and {len(only_in_local) - 5} more")

if only_in_remote:
    print("\nIssues only in REMOTE (CI):")
    for file, line, msg in sorted(only_in_remote)[:5]:
        print(f"  {file}:{line} - {msg[:60]}")
    if len(only_in_remote) > 5:
        print(f"  ... and {len(only_in_remote) - 5} more")
